import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_d = sum(1 for a in op if a == 'D')
    my_d = sum(1 for a in me if a == 'D')
    last_i = n - 1
    last_me, last_op = history[last_i]
    if n < 8:
        if last_op == 'D':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'C'
    opp_rate = opp_d / float(n)
    if opp_rate > 0.45:
        if last_op == 'D':
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if opp_rate > 0.75:
            if rng.random() < 0.25:
                return 'D'
        return 'C'
    if opp_rate < 0.12 and n > 20:
        if last_op == 'C':
            if rng.random() < 0.12:
                return 'D'
            return 'C'
        return 'C'
    recent = op[max(0, n - 8):]
    recent_d = sum(1 for a in recent if a == 'D')
    if recent_d >= 4:
        if last_op == 'D':
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    if last_op == 'D':
        if last_me == 'C':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'
    if n >= 4:
        last4 = op[-4:]
        if last4 == ['C', 'C', 'D', 'C']:
            if rng.random() < 0.35:
                return 'D'
        if last4 == ['D', 'C', 'C', 'C']:
            return 'C'
        if last4 == ['C', 'D', 'C', 'C']:
            return 'C'
    if n > 94:
        if opp_rate < 0.3:
            return 'C'
        if rng.random() < 0.4:
            return 'D'
        return 'C'
    if my_d > opp_d + 3 and opp_rate < 0.2:
        if rng.random() < 0.2:
            return 'D'
    return 'C'
